def commit(state, batch):
    # Deep copy state to not mutate caller-owned data
    result = {
        'balances': dict(state['balances']),
        'seen': {k: list(v) for k, v in state['seen'].items()}
    }
    for event, src, dst, amount in batch:
        # 1. Validity check: positive integer amount (not bool), existing distinct accounts
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError("invalid")
        if src not in result['balances'] or dst not in result['balances']:
            raise ValueError("invalid")
        if src == dst:
            raise ValueError("invalid")

        # 2. ID reuse check
        if event in result['seen']:
            if result['seen'][event] == [src, dst, amount]:
                continue  # skip identical transfer
            else:
                raise ValueError("conflict")

        # 3. Funds check
        if result['balances'][src] < amount:
            raise ValueError("funds")

        # 4. Apply transfer
        result['balances'][src] -= amount
        result['balances'][dst] += amount
        result['seen'][event] = [src, dst, amount]
    return result

