from ledger import commit


def restore(snapshot, batches):
    if isinstance(snapshot, dict) and 'balances' in snapshot and 'seen' in snapshot:
        state = {
            'balances': dict(snapshot['balances']),
            'seen': {k: list(v) for k, v in snapshot['seen'].items()}
        }
    else:
        state = {
            'balances': dict(snapshot),
            'seen': {}
        }
    rejected = []
    for index, batch in enumerate(batches):
        try:
            state = commit(state, batch)
        except ValueError:
            rejected.append(index)
    return [state, rejected]
